style.css:
@-moz-document domain("youtube.com") {
:root {
    color-scheme: dark;

    --starya-bg: #100e13;
    --starya-surface: #19151d;
    --starya-surface-hover: #241d29;
    --starya-text: #f3edf6;
    --starya-muted: #aaa0b2;
    --starya-accent: #c5f330;
    --starya-border: rgba(225, 210, 240, 0.12);
    --starya-radius: 16px;
  }

  html,
  body,
  ytd-app {
    background: var(--starya-bg) !important;
    color: var(--starya-text) !important;
  }

  /* Top navigation */

  ytd-masthead,
  #masthead-container,
  #background,
  tp-yt-app-header {
    background: var(--starya-bg) !important;
  }

  /* Sidebar */

  #guide-content,
  ytd-mini-guide-renderer,
  ytd-guide-renderer {
    background: var(--starya-bg) !important;
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    border-radius: 12px !important;
    transition: background 180ms ease;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: var(--starya-surface-hover) !important;
  }

  /* Search field */

  #center #search,
  ytd-searchbox {
    border-radius: 28px !important;
  }

  ytd-searchbox #container,
  #container.ytd-searchbox {
    background: var(--starya-surface) !important;
    border: 1px solid var(--starya-border) !important;
    border-radius: 28px !important;
  }

  #search-icon-legacy,
  ytd-searchbox button {
    border-radius: 0 28px 28px 0 !important;
  }

  /* Category chips */

  #chips-wrapper,
  ytd-feed-filter-chip-bar-renderer {
    background: var(--starya-bg) !important;
  }

  yt-chip-cloud-chip-renderer {
    border-radius: 10px !important;
    transition: background 180ms ease;
  }

  yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"] {
    background: var(--starya-surface) !important;
  }

  /* Video cards */

  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-compact-video-renderer,
  ytd-grid-video-renderer {
    border-radius: var(--starya-radius) !important;
  }

  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-grid-video-renderer {
    transition:
      transform 200ms ease,
      opacity 200ms ease;
  }

  ytd-rich-item-renderer:hover,
  ytd-video-renderer:hover,
  ytd-grid-video-renderer:hover {
    transform: translateY(-3px);
  }

  /* Thumbnails */

  ytd-thumbnail,
  yt-thumbnail-view-model,
  #thumbnail {
    border-radius: var(--starya-radius) !important;
    overflow: hidden !important;
  }

  ytd-thumbnail img,
  yt-thumbnail-view-model img {
    transition: transform 300ms ease !important;
  }

  ytd-rich-item-renderer:hover ytd-thumbnail img,
  ytd-video-renderer:hover ytd-thumbnail img {
    transform: scale(1.025);
  }

  /* Text */

  #video-title,
  yt-formatted-string,
  #channel-name {
    color: var(--starya-text);
  }

  #metadata-line,
  .inline-metadata-item {
    color: var(--starya-muted) !important;
  }

  /* Buttons */

  yt-button-shape button,
  ytd-button-renderer button {
    border-radius: 12px !important;
    transition:
      background 180ms ease,
      transform 180ms ease;
  }

  /* Player */

  .html5-video-player {
    border-radius: 16px !important;
    overflow: hidden !important;
  }

  /* Dialogs and menus */

  ytd-popup-container,
  tp-yt-paper-dialog,
  ytd-menu-popup-renderer,
  tp-yt-iron-dropdown {
    --yt-spec-menu-background: var(--starya-surface);
    --yt-spec-general-background-a: var(--starya-surface);
  }

  /* Accent details */

  a:hover,
  #video-title:hover {
    color: var(--starya-accent) !important;
  }

  /* Respect reduced-motion preferences */

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation: none !important;
      transition: none !important;
      scroll-behavior: auto !important;
    }
  }
}
